<script setup>
import { ref, computed, onMounted, watch } from 'vue'
import { useRouter, useRoute } from 'vue-router'
import dayjs from 'dayjs'
import api from '@/api'
import { ElMessage, ElMessageBox } from 'element-plus'

import {
  Monitor,
  House,
  ChatDotRound,
  Document,
  User,
  Calendar,
  Tools,
  Collection,
  UserFilled,
  ArrowDown,
  Bell,
  Tickets,
  Checked,
  Finished,
  Box,
  Setting,
  DocumentCopy,
  SwitchButton,
  MagicStick
} from '@element-plus/icons-vue'

const router = useRouter()
const route = useRoute()
const overdueCount = ref(0)
const approvalCount = ref(0)
const messageCount = ref(0)
const currentUser = ref(null)

// 页面标题映射
const pageTitleMap = {
  '/': '首页',
  '/messages': '消息中心',
  '/ai': 'AI助手',
  '/tasks': '任务管理',
  '/approvals': '审批管理',
  '/documents': '文档中心',
  '/calendar': '日历视图',
  '/equipments': '设备列表',
  '/categories': '设备分类',
  '/borrows': '借用管理',
  '/profiles': '用户管理',
  '/audit-logs': '审计日志',
  '/profile': '个人中心'
}

const getPageTitle = computed(() => {
  // 根据路由路径和用户角色动态返回标题
  const path = route.path
  if (path === '/tasks' && currentUser.value) {
    return ['管理员', '教师'].includes(currentUser.value.role) ? '任务管理' : '我的任务'
  }
  if (path === '/approvals' && currentUser.value) {
    return ['管理员', '教师'].includes(currentUser.value.role) ? '审批管理' : '我的申请'
  }
  return pageTitleMap[path] || '实验室管理系统'
})

const getRoleType = (role) => {
  const map = {
    '管理员': 'danger',
    '教师': 'warning',
    '导师': 'warning',
    '硕士生': 'success',
    '博士生': 'primary'
  }
  return map[role] || 'info'
}

watch(() => route.path, () => {
  if (route.name !== 'login' && !currentUser.value) {
    const userStr = localStorage.getItem('user')
    if (userStr) {
      currentUser.value = JSON.parse(userStr)
    }
  }
})

const handleCommand = (command) => {
  if (command === 'logout') {
    handleLogout()
  } else if (command === 'profile') {
    router.push('/profile')
  }
}

const handleLogout = () => {
  ElMessageBox.confirm('确定要退出登录吗？', '提示', {
    confirmButtonText: '确定',
    cancelButtonText: '取消',
    type: 'warning'
  }).then(() => {
    localStorage.removeItem('user')
    localStorage.removeItem('access_token')
    localStorage.removeItem('refresh_token')
    currentUser.value = null
    router.push('/login')
    ElMessage.success('已退出登录')
  }).catch(() => {})
}

const checkOverdue = async () => {
  try {
    const res = await api.getBorrows({ status: 'borrowed' })
    const borrows = res.data.results || res.data || []
    const now = dayjs()
    overdueCount.value = borrows.filter(b => now.isAfter(dayjs(b.expected_return_date))).length
  } catch (error) {
    console.error('检查逾期失败')
  }
}

const checkApprovals = async () => {
  try {
    if (!currentUser.value) return
    const params = { status: 'pending' }
    const currentProfileId = currentUser.value.id
    if (['管理员', '教师'].includes(currentUser.value.role)) {
      params.approver = currentProfileId
    } else {
      params.applicant = currentProfileId
    }
    const res = await api.getApprovals(params)
    const approvals = res.data.results || res.data || []
    approvalCount.value = approvals.length
  } catch (error) {
    console.error('检查审批失败', error)
  }
}

const checkMessages = async () => {
  try {
    if (!currentUser.value) return
    const res = await api.getMessageStats()
    // 后端返回的数据结构是 { stats: { unread_count: X, ... } }
    if (res.data && res.data.stats) {
      messageCount.value = res.data.stats.unread_count
    } else {
      // 降级处理：如果没有stats接口，则手动计算（兼容旧逻辑）
      const profileId = currentUser.value.id
      const listRes = await api.getMessages(profileId)
      const messages = listRes.data.results || listRes.data || []
      messageCount.value = messages.filter((m) => !m.is_read).length
    }
  } catch (error) {
    console.error('检查消息失败', error)
  }
}

onMounted(() => {
  const userStr = localStorage.getItem('user')
  if (userStr) {
    currentUser.value = JSON.parse(userStr)
  }

  checkOverdue()
  checkApprovals()
  checkMessages()

  window.addEventListener('approval-updated', checkApprovals)
  window.addEventListener('message-updated', () => {
    // 稍微延迟一下，确保后端事务已提交
    setTimeout(checkMessages, 200)
  })

  setInterval(() => {
    checkOverdue()
    checkApprovals()
    checkMessages()
  }, 30 * 1000)
})
</script>

